"schemas" = "kintsugi/_schemas"

[tool.ruff]
line-length = 100
target-version = "py312"
extend-exclude = [".claude", ".entire"]

[tool.ruff.lint]
select = ["B", "C4", "E", "F", "I", "PIE", "PT", "RUF", "SIM", "TID", "UP", "W"]
# Spec notation (Ω, σ, τ, φ, ×, ‖, en/em dashes) is intentional, not a confusable.
allowed-confusables = ["×", "‖", "–", "—", "−", "′", "″", "Ω", "α", "β", "δ", "κ", "λ", "σ", "τ", "φ", "ψ", "ι", "ρ", "∗"]

[tool.ruff.lint.isort]
known-first-party = ["kintsugi", "hostkit", "ledger", "scout", "triage"]

# Every child process goes through kintsugi.sandbox.proc (docs/EXECUTION_PLAN.md §2d).
[tool.ruff.lint.flake8-tidy-imports.banned-api]
"subprocess".msg = "Use kintsugi.sandbox.proc: the single gateway (ENTIRE_TEST_TTY=0, env allowlist, tree kill)."
"os.system".msg = "Use kintsugi.sandbox.proc.run."
"os.popen".msg = "Use kintsugi.sandbox.proc.run."
"asyncio.create_subprocess_exec".msg = "Use kintsugi.sandbox.proc."
"asyncio.create_subprocess_shell".msg = "Use kintsugi.sandbox.proc."

[tool.ruff.lint.per-file-ignores]
"kintsugi/sandbox/proc.py" = ["TID251"]

[tool.pyright]
include = ["kintsugi", "tests", "hosts"]
exclude = ["tests/fixtures"]  # fixture repos import their own packages (ledger.*, scout.*)
pythonVersion = "3.12"
typeCheckingMode = "standard"
reportMissingTypeStubs = false
stubPath = "typings"
venvPath = "."
venv = ".venv"

[tool.pytest.ini_options]
testpaths = ["tests", "hosts"]
pythonpath = ["."]
addopts = "-ra --strict-markers --import-mode=importlib"
markers = [
    "contract: needs local Entire or Claude Code tooling (Stage 2+)",
    "slow: long-running",
]
# Secrets and credentials — never commit
.env
*.csv
*accessKeys*
*credentials*
*.key
*.age
# Sealed holdouts are encrypted to .kintsugi/holdout.pub and committed (spec §6.1, audit C13).
!hosts/*/*/evals/holdout/*.age

# Runtime state: the deploy worktree, live-traffic rows, the spend ledger, the senses store and
# the ingress secrets
.state/
# Raw webhook payloads: kept as evidence, published only inside proof bundles (Stage 8)
evidence/ingress/

# Python
__pycache__/
*.pyc
.venv/
.pytest_cache/
.ruff_cache/
.hypothesis/
dist/
build/

# Node
node_modules/

# Allow the business-plan actuals export (spec §4.6.5)
!business/actuals.csv

# Re-assert after the exception: secrets stay ignored everywhere, business/ included
*accessKeys*
*credentials*
commit-msg
post-commit
post-rewrite
pre-push
