    hits = {n for n in impacted if n in patched or _short(n) in short_patched}
    return Reverify(old_main, new_main, head, _sorted(changed), _sorted(patched),
                    _sorted(impacted), _sorted(hits), _sorted(tests))  # fmt: skip


